import 'dart:convert';
import 'dart:io';

import 'package:latlong2/latlong.dart';
import 'package:roadstr/services/search_response_protocol.dart';

const outputPath =
    'android/app/src/test/resources/parity/search_responses_v1.tsv';

typedef _Case = ({
  String operation,
  String name,
  LatLng center,
  String? fallbackName,
  String input,
});

String buildSearchResponsesFixture() {
  final rows = <String>[
    '# Generated by tools/kotlin_rewrite/generate_search_responses_fixture.dart.',
    '# operation\tname\tcenter_lat\tcenter_lon\tfallback_b64\tinput_b64\texpected_b64',
  ];
  for (final value in _cases()) {
    rows.add([
      value.operation,
      value.name,
      value.center.latitude,
      value.center.longitude,
      value.fallbackName == null ? '-' : _encode(value.fallbackName!),
      _encode(value.input),
      _encode(_evaluate(value)),
    ].join('\t'));
  }
  return '${rows.join('\n')}\n';
}

String _evaluate(_Case value) {
  try {
    return switch (value.operation) {
      'nominatim' => _canonicalResults(
          SearchResponseProtocol.parseNominatimSearch(value.input),
        ),
      'reverse' => _canonicalReverse(
          SearchResponseProtocol.parseNominatimReverse(value.input),
        ),
      'photon' => _canonicalResults(
          SearchResponseProtocol.parsePhoton(value.input),
        ),
      'overpass' => _canonicalResults([
          for (final element
              in SearchResponseProtocol.parseOverpassElements(value.input))
            if (SearchResponseProtocol.overpassElementToResult(
              element,
              value.center,
              fallbackName: value.fallbackName,
            )
                case final result?)
              result,
        ]),
      'overpass_elements' => _canonicalElements(
          SearchResponseProtocol.parseOverpassElements(value.input),
        ),
      _ => throw StateError('Unknown operation ${value.operation}'),
    };
  } catch (_) {
    return 'error';
  }
}

String _canonicalResults(List<NominatimResult> results) => [
      'count=${results.length}',
      'items=${results.map(_canonicalResult).join(';')}',
    ].join('\n');

String _canonicalResult(NominatimResult result) => [
      _encode(result.displayName),
      _encode(result.shortName),
      _f6(result.position.latitude),
      _f6(result.position.longitude),
      _optional(result.cls),
      _optional(result.type),
      _optional(result.city),
      _optional(result.openingHours),
      result.distanceM == null ? '-' : _f3(result.distanceM!),
      _optional(result.brand),
      _encode(result.emoji),
      _encode(result.categoryLabel),
    ].join(',');

String _canonicalReverse(NominatimReverseDetail? detail) => detail == null
    ? 'null'
    : [
        'display=${_encode(detail.display)}',
        'wiki=${_optional(detail.wikiQuery)}',
        'opening=${_optional(detail.openingHours)}',
        'label=${_encode(detail.label)}',
      ].join('\n');

String _canonicalElements(List<Map<String, dynamic>> elements) => [
      'count=${elements.length}',
      'items=${elements.map((element) {
        final type = element['type'];
        final id = element['id'];
        final keys = element.keys.toList()..sort();
        return '${_encode(type is String ? type : '')},'
            '${id is num ? id : '-'},${keys.map(_encode).join('.')}';
      }).join(';')}',
    ].join('\n');

String _optional(String? value) => value == null ? '-' : _encode(value);

String _f3(double value) => value.toStringAsFixed(3);

String _f6(double value) => value.toStringAsFixed(6);

