Map<String, dynamic> _nominatim({
  required String lat,
  required String lon,
  required String display,
  String? cls,
  String? type,
  Map<String, Object?>? address,
  Map<String, Object?>? extra,
}) =>
    {
      'lat': lat,
      'lon': lon,
      'display_name': display,
      if (cls != null) 'class': cls,
      if (type != null) 'type': type,
      if (address != null) 'address': address,
      if (extra != null) 'extratags': extra,
    };

Map<String, dynamic> _photon({
  required Object lon,
  required Object lat,
  required Map<String, Object?> properties,
}) =>
    {
      'type': 'Feature',
      'geometry': {
        'type': 'Point',
        'coordinates': [lon, lat],
      },
      'properties': properties,
    };

Map<String, dynamic> _node(
  int id,
  Object lat,
  Object lon,
  Map<String, Object?> tags,
) =>
    {'type': 'node', 'id': id, 'lat': lat, 'lon': lon, 'tags': tags};

_Case _jsonCase(
  String operation,
  String name,
  Object? input, {
  LatLng center = const LatLng(0, 0),
  String? fallbackName,
}) =>
    (
      operation: operation,
      name: name,
      center: center,
      fallbackName: fallbackName,
      input: jsonEncode(input),
    );

_Case _rawCase(
  String operation,
  String name,
  String input, {
  LatLng center = const LatLng(0, 0),
  String? fallbackName,
}) =>
    (
      operation: operation,
      name: name,
      center: center,
      fallbackName: fallbackName,
      input: input,
    );

String _encode(String value) =>
    base64Url.encode(utf8.encode(value)).replaceAll('=', '');

void main(List<String> arguments) {
  final generated = buildSearchResponsesFixture();
  final output = File(outputPath);
  if (arguments.contains('--check')) {
    if (!output.existsSync() || output.readAsStringSync() != generated) {
      stderr.writeln('$outputPath is stale; regenerate it.');
      exitCode = 1;
    }
    return;
  }
  output.parent.createSync(recursive: true);
  output.writeAsStringSync(generated);
}
